mapper.sql:
WHERE r.is_deleted = 0

    AND r.receipt_no LIKE CONCAT('%', #{receiptNo}, '%')


    AND r.order_no LIKE CONCAT('%', #{orderNo}, '%')


    AND r.user_id = #{userId}


    AND r.channel = #{channel}


    AND r.status = #{status}


    AND r.paid_at >= #{start}


    AND r.paid_at <= #{end}

mapper.select:
SELECT 


ORDER BY r.paid_at DESC, r.id DESC
LIMIT #{offset}, #{pageSize}

mapper.update:
UPDATE finance_receipt
SET remark = #{remark}, update_time = #{now}
WHERE id = #{id} AND is_deleted = 0

mapper.select:
SELECT COALESCE(SUM(amount), 0)
FROM finance_receipt
WHERE is_deleted = 0 AND status = 1

    AND paid_at >= #{start}


    AND paid_at <= #{end}

SELECT COALESCE(SUM(a.refund_amount), 0) FROM after_sales a LEFT JOIN after_sale_only_refunds r1 ON r1.after_sale_id = a.id AND r1.is_deleted = 0 LEFT JOIN after_sale_returns r2 ON r2.after_sale_id = a.id AND r2.is_deleted = 0 WHERE a.is_deleted = 0 AND a.status = 'refunded'
AND COALESCE(r2.refunded_at, r1.refunded_at, a.updated_at) >= #{start}
AND COALESCE(r2.refunded_at, r1.refunded_at, a.updated_at) <= #{end}
